// Keyboard text entry is fed by the plugin's slot-14 hook (see aio_plugin_key) into ConfigPage's
// feed_char/backspace/enter while the name field is focused -- the hook CONSUMES those keys so the
// game never sees them. No per-frame Win32 polling here.

static const char* TABS[]     = { "Configuration", "Profile", "Edit Layout", "Help", "Update", "Debug" };

// What the Status-icons row SHOWS for a pack. Only the four built-in entries are translated -- an XIPivot pack
// is shown under its folder name, which is how the player recognises it and what they see in XIPivot itself.
// The stored name (ui_config().iconPack) is always the English one : a config written in French must still
// load in English, and a folder name is not ours to translate anyway.
static const char* icon_pack_label(const IconPack& p) {
    switch (p.kind) {
        case IPK_BUNDLED: return tr("AioPack", "AioPack");
        case IPK_CUSTOM:  return tr("My sheet", "Ma feuille");
        case IPK_GAME:    return tr("Game", "Jeu");
        // Auto stays a bare word on purpose. It is a MODE -- "follow whatever icons this install has" -- and
        // it necessarily resolves to one of the sources listed below it, so naming that source here only makes
        // the row look like it holds the same pack twice. It was tried the other way round: spelling out
        // "Auto (AioPack)" read as a duplicate entry rather than as an explanation. What it settled on is in
        // the log (//aio selfcheck), which is where you look when the icons are not the ones you expected.
        case IPK_AUTO:    return tr("Auto", "Auto");
        default: return p.name;
    }
}
static const char* LOGO_PATH() { static char b[260]; if (!b[0]) plugin_path(b, 260, "assets\\aiohud_logo.raw"); return b; }
static const int   NTABS      = 6;
static const char* tab_label(int i) {
    static const char* en[] = { "Configuration", "Profile", "Edit Layout", "Help", "Update", "Debug" };
    static const char* fr[] = { "Configuration", "Profil", "\xC3\x89""diter dispo", "Aide", "Mise \xC3\xA0 jour", "Debug" };
    return (ui_config().lang == 1 ? fr : en)[i];
}

